package ca.yorku.eecs3311.coursepilot.application.service;
import ca.yorku.eecs3311.coursepilot.application.dto.ProgressSummary; import java.time.*; import java.util.*;
public class BalancedStudyStrategy implements StudyPlanningStrategy {public String name(){return "BALANCED";}public List<Activity> build(LocalDate start,LocalDate target,int minutes,List<ProgressSummary.TopicProgress> topics){return distribute(start,target,minutes,topics,"Review");}static List<Activity> distribute(LocalDate start,LocalDate target,int minutes,List<ProgressSummary.TopicProgress> topics,String verb){List<String> names=topics.isEmpty()?List.of("course material"):topics.stream().map(ProgressSummary.TopicProgress::topic).toList();long days=java.time.temporal.ChronoUnit.DAYS.between(start,target)+1;int slots=(int)Math.min(days,Math.max(1,minutes/30));List<Activity> out=new ArrayList<>();int base=minutes/slots,remainder=minutes%slots;for(int i=0;i<slots;i++){String topic=names.get(i%names.size());out.add(new Activity(start.plusDays(i*Math.max(1,days/slots)),verb+" "+topic,base+(i<remainder?1:0)));}return out;}}
